  // Initialize and compile pre-computed search arrays and regex per language pack
  const T_REVERSE = {};

  function compileLangPack(pack) {
    if (!pack) return;
    const t = pack.T || {};
    for (const en in t) {
      T_REVERSE[t[en]] = en;
    }
    const tKeys = Object.keys(t).sort((a, b) => b.length - a.length);
    pack.SORTED_T_KEYS = tKeys;
    pack.MULTI_WORD_KEYS = tKeys.filter(k => k.length > 2 && k.includes(' '));

    const wl = pack.WORD_LEXICON || {};
    for (const k of Object.keys(wl)) { const lk = k.toLowerCase(); if (lk !== k && !wl[lk]) wl[lk] = wl[k]; }
    const wlKeys = Object.keys(wl).sort((a, b) => b.length - a.length);
    pack.WORD_KEYS = wlKeys;
    // v50: Tier 3 uses a Unicode tokenizer + O(1) lexicon lookups (no giant alternation regex)
  }

  for (const langCode in LANG_PACKS) {
    compileLangPack(LANG_PACKS[langCode]);
  }

  function matchCase(sourceWord, targetPhrase) {
    if (!sourceWord || !targetPhrase) return targetPhrase;
    if (sourceWord === sourceWord.toUpperCase() && sourceWord.length > 1) {
      return targetPhrase.toUpperCase();
    }
    if (sourceWord[0] === sourceWord[0].toUpperCase() && sourceWord.slice(1) === sourceWord.slice(1).toLowerCase()) {
      return targetPhrase.charAt(0).toUpperCase() + targetPhrase.slice(1);
    }
    return targetPhrase;
  }

