  let isApplying = false;

  // State Management — Initial Launch State & Admin Overrides
  function loadInitialState() {
    // 1. Apply any admin-configured regional default languages from storage
    try {
      const adminDefaults = JSON.parse(localStorage.getItem('synergy_market_defaults') || '{}');
      for (const mCode in adminDefaults) {
        if (MARKETS[mCode] && (SUPPORTED_LANGUAGES[adminDefaults[mCode]] || adminDefaults[mCode] === 'en')) {
          MARKETS[mCode].defaultLang = adminDefaults[mCode];
        }
      }
    } catch (_) {}

    let market = localStorage.getItem('synergy_market') || 'KE';
    let lang = localStorage.getItem('synergy_lang') || (MARKETS[market] ? MARKETS[market].defaultLang : 'en');
    let currency = localStorage.getItem('synergy_currency') || (MARKETS[market] ? MARKETS[market].currency : 'KES');

    const savedRegion = localStorage.getItem('tunemaven_region');
    if (savedRegion) {
      try {
        const parsed = JSON.parse(savedRegion);
        if (parsed.country && MARKETS[parsed.country] && !localStorage.getItem('synergy_market')) {
          market = parsed.country;
        }
        if (parsed.currency && CURRENCIES[parsed.currency] && !localStorage.getItem('synergy_currency')) {
          currency = parsed.currency;
        }
        if (parsed.language && (SUPPORTED_LANGUAGES[parsed.language] || parsed.language === 'en') && !localStorage.getItem('synergy_lang')) {
          lang = parsed.language;
        }
      } catch (_) {}
    }

    if (!MARKETS[market]) market = 'KE';
    if (!CURRENCIES[currency]) currency = MARKETS[market].currency || 'KES';
    if (!SUPPORTED_LANGUAGES[lang]) lang = MARKETS[market].defaultLang || 'en';

    return { market, lang, currency };
  }

  const initialState = loadInitialState();
  let currentMarket = initialState.market;
  let currentLang = initialState.lang;
  let currentCurrency = initialState.currency;

  function persistState() {
    try {
      localStorage.setItem('synergy_market', currentMarket);
      localStorage.setItem('synergy_lang', currentLang);
      localStorage.setItem('synergy_currency', currentCurrency);
      localStorage.setItem('tunemaven_region', JSON.stringify({
        country: currentMarket,
        currency: currentCurrency,
        language: currentLang
      }));
    } catch (_) {}
  }

  persistState();

  // Convert USD or KES amounts in text to active currency
  function formatCurrencyAmount(usdAmount, targetCurrCode) {
    const curr = CURRENCIES[targetCurrCode] || CURRENCIES.KES;
    const raw = usdAmount * curr.usdRate;
    let formattedNum;
    if (curr.code === 'USD' || curr.code === 'GBP' || curr.code === 'EUR') {
      if (Number.isInteger(usdAmount) || raw >= 100) {
        formattedNum = Math.round(raw).toLocaleString('en-US');
      } else {
        formattedNum = raw.toFixed(2);
      }
      return curr.symbol + formattedNum;
    } else {
      const rounded = raw < 10 ? raw.toFixed(2) : Math.round(raw).toLocaleString('en-US');
      return curr.symbol + ' ' + rounded;
    }
  }

  function convertCurrencyInText(text, targetCurrCode, lang) {
    if (!text) return text;
    let result = text;

    if (targetCurrCode !== 'USD' && result.includes('$')) {
      result = result.replace(/\$\s*(\d{1,3}(?:,\d{3})*(?:\.\d{1,2})?|\d+(?:\.\d{1,2})?)(\s*(?:Million|Billion|Milioni|Bilioni|Millones|M|B|k|K))?(?:\s*USD)?/g, (match, numStr, scaleStr) => {
        const cleanNum = parseFloat(numStr.replace(/,/g, ''));
        if (isNaN(cleanNum)) return match;
        const curr = CURRENCIES[targetCurrCode] || CURRENCIES.KES;
        if (scaleStr) {
          const scaledVal = Math.round(cleanNum * curr.usdRate * 10) / 10;
          let scaleWord = scaleStr.trim();
          if (lang === 'sw' || lang === 'ki') {
            if (/million|millones/i.test(scaleWord)) scaleWord = 'Milioni';
            if (/billion/i.test(scaleWord)) scaleWord = 'Bilioni';
          } else if (lang === 'es') {
            if (/million|milioni/i.test(scaleWord)) scaleWord = 'Millones';
            if (/billion|bilioni/i.test(scaleWord)) scaleWord = 'Miles de Millones';
          }
          return curr.symbol + ' ' + scaledVal.toLocaleString('en-US') + ' ' + scaleWord;
        }
        return formatCurrencyAmount(cleanNum, targetCurrCode);
      });
    }

    if (targetCurrCode !== 'KES' && (/\b(?:KES|KSh)\s*\d/i.test(result))) {
      result = result.replace(/\b(?:KES|KSh)\s*(\d{1,3}(?:,\d{3})*(?:\.\d{1,2})?|\d+(?:\.\d{1,2})?)/gi, (match, numStr) => {
        const cleanKes = parseFloat(numStr.replace(/,/g, ''));
        if (isNaN(cleanKes)) return match;
        const usdEquiv = cleanKes / 130.0;
        return formatCurrencyAmount(usdEquiv, targetCurrCode);
      });
    }

    return result;
  }

